// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 _basefee, uint64 _number, uint64 _timestamp, bytes32 _hash, uint64 _seq, bytes32 _batcherHash, uint256 _overhead, uint256 _scalar) public {
        address depositor = c.depositorAccount();
        vm.prank(depositor);
        c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _seq, _batcherHash, _overhead, _scalar);
        assertTrue(c.basefee() == 0);
    }
}
